mapper.select:
select id, batch_id, user_id, status, claimed_at, used_at, created_at, updated_at
from user_coupon
where batch_id = #{batchId}
  and user_id = #{userId}
limit 1

mapper.update:
update user_coupon
set status = #{status},
    used_at = case when #{status} = 'USED' then current_timestamp else used_at end
where id = #{id}
  and user_id = #{userId}
  and status = 'UNUSED'
